        var cx = c.x - T.x, cy = c.y - T.y;
        if (cx * cx + cy * cy <= r2) cands.push(c);
      }
      if (cands.length === 0) continue;
      var tgt = null;
      if (hasTarget) {
        var views = [];
        for (var vi = 0; vi < cands.length; vi++) views.push(view(cands[vi]));
        var pick = strat.target({ slot: ts, type: T.type, tier: T.tier, x: T.x, y: T.y, range: T.range }, views);
