          if (q.hp <= 0 || (q.air ? !D.a : !D.g)) continue;
          var qx = q.x - tgt.x, qy = q.y - tgt.y;
          if (qx * qx + qy * qy <= s2) hits.push(q);
        }
      } else hits = [tgt];
      for (var hk = 0; hk < hits.length; hk++) {
        var v = hits[hk];
        v.hp -= D.pierce ? T.dmg : Math.max(1, T.dmg - v.armor);
        if (D.slow > 0) v.slow = D.slow;
      }
      T.cd = D.period;
      if (rec && rec.onShot) rec.onShot(tick, T, tgt, hits);
      var alive = [], spawned = [];
      for (var ki = 0; ki < enemies.length; ki++) {
        var k = enemies[ki];
        if (k.hp > 0) { alive.push(k); continue; }
        gold += k.bounty;
        log.push([tick, "K", k.id, ts]);
        if (rec && rec.onKill) rec.onKill(tick, k, ts);
        if (k.type === "splitter") {
          var sh = Math.max(1, Math.floor(k.maxHp / 4));
          for (var sp = 0; sp < 3; sp++) spawned.push(makeEnemy("splitling", k.wave, sh, k.progress));
        }
      }
      enemies = spawned.length ? alive.concat(spawned) : alive;
    }
    // 6. slow timers
    for (var sj = 0; sj < enemies.length; sj++) if (enemies[sj].slow > 0) enemies[sj].slow--;
    if (rec && rec.onTick) rec.onTick(tick, enemies, turrets, gold, baseHp, wave);
  }
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
