  for (var u = 0; u < json.length; u++) { hsh ^= json.charCodeAt(u); hsh = Math.imul(hsh, 0x01000193); }
  var hash = ("0000000" + (hsh >>> 0).toString(16)).slice(-8);
  return { score: score, fallTick: fallTick, log: log, hash: hash };
}

