  }
  function view(e) {
    var R = e.air ? AIR : GROUND;
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow, remaining: R.len - e.progress };
  }
  function turretStats(t) {
    var d = TT[t.ti], dmg = d.dmg, rg = d.range;
    for (var k = 1; k < t.tier; k++) { dmg = Math.floor(dmg * 16 / 10); rg += 30; }
    t.dmg = dmg; t.range = rg;
  }
  function applyActions(acts) {
    if (!acts || typeof acts.length !== "number") return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var sl = a.slot;
      if (typeof sl !== "number" || !(sl >= 0 && sl < 16) || Math.floor(sl) !== sl) continue;
      var t = turrets[sl];
      if (a.op === "build") {
        if (t || typeof a.type !== "string" || !TIDX.hasOwnProperty(a.type)) continue;
        var ti = TIDX[a.type], c = TT[ti].cost;
        if (gold < c) continue;
        gold -= c;
        t = { slot: sl, ti: ti, type: a.type, tier: 1, spent: c, cd: 0, x: SLOTS[sl][0] * 100 + 50, y: SLOTS[sl][1] * 100 + 50, dmg: 0, range: 0 };
        turretStats(t); turrets[sl] = t;
        log.push([tick, "B", sl, ti]);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        var uc = TT[t.ti].cost * (t.tier === 1 ? 1 : 2);
        if (gold < uc) continue;
        gold -= uc; t.spent += uc; t.tier++; turretStats(t);
        log.push([tick, "U", sl, t.tier]);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
        turrets[sl] = null;
        log.push([tick, "S", sl, 0]);
      }
    }
  }

  var hasTarget = typeof strat.target === "function";
  var ended = false;
  for (tick = 0; tick < maxTicks && !ended; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waveComp[wave + 1] = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: waveComp[wave + 1].slice() };
      for (var si = 0; si < 16; si++) {
        var tu = turrets[si];
        st.slots.push({ slot: si, x: SLOTS[si][0], y: SLOTS[si][1], turret: tu ? { type: tu.type, tier: tu.tier, spent: tu.spent } : null });
      }
      for (var ei = 0; ei < enemies.length; ei++) st.enemies.push(view(enemies[ei]));
      applyActions(strat.plan(st));
      var comp = waveComp[wave];
      for (var qi = 0; qi < comp.length; qi++) {
        var at = tick + 4 * qi;
        (spawnsAt[at] || (spawnsAt[at] = [])).push({ type: comp[qi], wave: wave });
      }
      delete waveComp[wave];
    }
    // 2. spawn
    var due = spawnsAt[tick];
    if (due) {
      for (var di = 0; di < due.length; di++) {
        var ww = due[di].wave;
        enemies.push(makeEnemy(due[di].type, ww, Math.floor(ET[due[di].type].hp * mult(ww) / 1000), 0));
      }
      delete spawnsAt[tick];
    }
    // 3. move
    var kept = [];
    for (var mi = 0; mi < enemies.length; mi++) {
      var e = enemies[mi];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      var RL = e.air ? AIR.len : GROUND.len;
      if (e.progress >= RL) {
        baseHp -= e.leak;
        log.push([tick, "L", e.id, baseHp]);
        if (rec && rec.onLeak) rec.onLeak(tick, e, baseHp);
        if (baseHp <= 0) {
          log.push([tick, "F", wave, 0]);
          fallTick = tick; ended = true;
          for (var rj = mi + 1; rj < enemies.length; rj++) kept.push(enemies[rj]);
          break;
        }
        continue;
      }
      place(e);
      kept.push(e);
    }
    enemies = kept;
    if (ended) { if (rec && rec.onTick) rec.onTick(tick, enemies, turrets, gold, baseHp, wave); break; }
    // 4. age & heal
    for (var ai = 0; ai < enemies.length; ai++) {
      var m = enemies[ai];
      m.age++;
      if (m.type === "mender" && m.age % 20 === 0) {
        for (var hi = 0; hi < enemies.length; hi++) {
          var h = enemies[hi], hx = h.x - m.x, hy = h.y - m.y;
          if (hx * hx + hy * hy <= 22500) {
