        }
      } else hits = [tgt];
      for (var hk = 0; hk < hits.length; hk++) {
        var v = hits[hk];
        v.hp -= D.pierce ? T.dmg : Math.max(1, T.dmg - v.armor);
        if (D.slow > 0) v.slow = D.slow;
      }
      T.cd = D.period;
      if (rec && rec.onShot) rec.onShot(tick, T, tgt, hits);
      var alive = [], spawned = [];
      for (var ki = 0; ki < enemies.length; ki++) {
        var k = enemies[ki];
        if (k.hp > 0) { alive.push(k); continue; }
