          for (var sp = 0; sp < 3; sp++) spawned.push(makeEnemy("splitling", k.wave, sh, k.progress));
        }
      }
      enemies = spawned.length ? alive.concat(spawned) : alive;
    }
    // 6. slow timers
    for (var sj = 0; sj < enemies.length; sj++) if (enemies[sj].slow > 0) enemies[sj].slow--;
