// parameterized strategy for tuning
function makeStrat(P) {
  return function createStrategy() {
    var SL = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
    var BASE = { bolt: [50, 26], cannon: [90, 60], frost: [70, 10], lance: [120, 180], flak: [80, 40] };
    function dmgOf(type, tier) { var d = BASE[type][1]; for (var k = 1; k < tier; k++) d = Math.floor(d * 16 / 10); return d; }
    var order = P.order; // array of [slot, type] or [slot] for upgrade
    var lastHp = 10, panic = false;
    function plan(s) {
      if (s.baseHp < lastHp) panic = true;
      lastHp = s.baseHp;
      var gold = s.gold, acts = [];
      var reserve = (panic || s.wave >= P.dumpWave) ? 0 : Math.min(P.reserve, Math.floor(P.resFrac * s.wave * 40));
      var tur = []; for (var i = 0; i < 16; i++) { var t = s.slots[i].turret; tur.push(t ? { type: t.type, tier: t.tier } : null); }
      for (var k = 0; k < order.length && acts.length < 32; k++) {
        var o = order[k], sl = o[0];
        if (o.length === 2) {
          if (tur[sl]) continue;
          var c = BASE[o[1]][0];
          if (gold - c < reserve) break;
          gold -= c; tur[sl] = { type: o[1], tier: 1 }; acts.push({ op: "build", slot: sl, type: o[1] });
        } else {
          var t2 = tur[sl];
          if (!t2) continue; // not built yet -> skip
          if (t2.tier >= o[1]) continue;
          var uc = BASE[t2.type][0] * (t2.tier === 1 ? 1 : 2);
          if (gold - uc < reserve) break;
          gold -= uc; t2.tier++; acts.push({ op: "upgrade", slot: sl });
          k--; // allow repeated upgrade to the requested tier
        }
      }
      return acts;
    }
    function target(t, cands) {
      var type = t.type, d = dmgOf(type, t.tier), n = cands.length, best = null, bs = -1e18, i, j, c;
      if (type === "cannon" || type === "flak") {
        var r2 = type === "cannon" ? 8100 : 4900;
        for (i = 0; i < n; i++) {
          c = cands[i]; var sc = 0;
          for (j = 0; j < n; j++) {
            var e = cands[j], dx = e.x - c.x, dy = e.y - c.y;
            if (dx * dx + dy * dy <= r2) { var ef = Math.max(1, d - e.armor); sc += Math.min(e.hp, ef) + (e.hp <= ef ? P.killBonus : 0) + (e.type === "mender" ? P.menderBonus : 0); }
          }
          sc = sc * 10000 - c.remaining;
          if (sc > bs) { bs = sc; best = c; }
        }
        return best.id;
      }
      if (type === "lance") {
        for (i = 0; i < n; i++) {
          c = cands[i];
          var sc2 = Math.min(c.hp, d) + c.armor * P.lanceArmor + (c.type === "mender" ? P.menderBonus * 3 : 0);
          sc2 = sc2 * 10000 - c.remaining;
          if (sc2 > bs) { bs = sc2; best = c; }
        }
        return best.id;
      }
      if (type === "frost") {
        for (i = 0; i < n; i++) {
          c = cands[i];
          var sc3 = (c.slowed ? 0 : 1e6) + (c.type === "splitling" ? 0 : 1e5) - c.remaining;
          if (sc3 > bs) { bs = sc3; best = c; }
        }
        return best.id;
      }
      // bolt
      for (i = 0; i < n; i++) {
        c = cands[i]; var ef2 = Math.max(1, d - c.armor);
        var sc4 = (c.type === "mender" ? 1e7 : 0) + (c.hp <= ef2 ? 1e6 : 0) + Math.min(ef2, c.hp) * 1000 - c.remaining;
        if (sc4 > bs) { bs = sc4; best = c; }
      }
      return best.id;
    }
    return { plan: plan, target: P.noTarget ? undefined : target };
  };
}

