load("sim.js"); load(arguments[0]);
var ITERS = parseInt(arguments[1] || "500"), RSEED = parseInt(arguments[2] || "1");
var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
function genomeToP(g) {
  var cnt = [], order = [];
  for (var s = 0; s < 16; s++) cnt.push(0);
  for (var i = 0; i < g.seq.length; i++) {
    var s2 = g.seq[i]; cnt[s2]++;
    if (cnt[s2] === 1) order.push([s2, g.types[s2]]); else order.push([s2, cnt[s2]]);
  }
  var P = {}; for (var k in g.par) P[k] = g.par[k];
  P.order = order; return P;
}
var TRAIN = [], VAL = [];
for (var i = 1; i <= 24; i++) TRAIN.push(i * 7919 + 13);
for (var j = 1; j <= 24; j++) VAL.push(j * 104729 + 7);
function evalG(g, seeds) {
  var P = genomeToP(g), sum = 0;
  for (var i = 0; i < seeds.length; i++) sum += rampartSimulate(makeStrat(P), seeds[i], 12020).score;
  return sum / seeds.length;
}
var rs = RSEED >>> 0;
function rnd() { rs = (rs + 0x6D2B79F5) | 0; var t = Math.imul(rs ^ (rs >>> 15), 1 | rs); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function ri(n) { return Math.floor(rnd() * n); }
function clone(g) { return JSON.parse(JSON.stringify(g)); }
function valid(g) { // each slot's tokens: build first; enforce by counting - always fine since tokens are identical per slot
  return true; }
var PARAM_RANGES = PRANGES;
function mutate(g) {
  var h = clone(g), m = ri(10);
  if (m < 4) { // move a token
    var a = ri(h.seq.length), b = ri(h.seq.length), t = h.seq.splice(a, 1)[0]; h.seq.splice(b, 0, t);
  } else if (m < 6) { // swap adjacent-ish
    var a2 = ri(h.seq.length), b2 = Math.min(h.seq.length - 1, Math.max(0, a2 + ri(7) - 3)), t2 = h.seq[a2]; h.seq[a2] = h.seq[b2]; h.seq[b2] = t2;
  } else if (m < 8) { // change type
    h.types[ri(16)] = TYPES[ri(5)];
  } else if (m < 9) { // swap types of two slots
    var s1 = ri(16), s2 = ri(16), tt = h.types[s1]; h.types[s1] = h.types[s2]; h.types[s2] = tt;
  } else {
    var keys = Object.keys(PARAM_RANGES), k = keys[ri(keys.length)], R = PARAM_RANGES[k];
    var v = h.par[k] + (rnd() < 0.5 ? -1 : 1) * R[2] * (1 + ri(3));
    h.par[k] = Math.max(R[0], Math.min(R[1], v));
  }
  return h;
}
var cur = INIT, curS = evalG(cur, TRAIN), best = clone(cur), bestS = curS;
print("init", curS.toFixed(3), "val", evalG(cur, VAL).toFixed(3));
var T0 = 0.4;
for (var it = 0; it < ITERS; it++) {
  var cand = mutate(cur);
  if (rnd() < 0.3) cand = mutate(cand);
  var s = evalG(cand, TRAIN);
  var temp = T0 * (1 - it / ITERS);
  if (s >= curS || rnd() < Math.exp((s - curS) / Math.max(1e-6, temp))) { cur = cand; curS = s; }
  if (s > bestS) { best = clone(cand); bestS = s; print("it", it, "best", bestS.toFixed(3)); }
}
print("final train", bestS.toFixed(3), "val", evalG(best, VAL).toFixed(3));
print("GENOME", JSON.stringify(best));

