function makeStrat(P) {
  return function createStrategy() {
    var BASE = { bolt: [50, 26], cannon: [90, 60], frost: [70, 10], lance: [120, 180], flak: [80, 40] };
    function dmgOf(type, tier) { var d = BASE[type][1]; for (var k = 1; k < tier; k++) d = Math.floor(d * 16 / 10); return d; }
    var order = P.order;
    var lastHp = 10, panic = false;
    function plan(s) {
      if (s.baseHp < lastHp) panic = true;
      lastHp = s.baseHp;
      var gold = s.gold, acts = [];
      var reserve = (panic || s.wave >= P.dumpWave) ? 0 : Math.min(P.reserve, s.wave * P.resRate);
      var tur = []; for (var i = 0; i < 16; i++) { var t = s.slots[i].turret; tur.push(t ? { type: t.type, tier: t.tier } : null); }
      for (var k = 0; k < order.length && acts.length < 32; k++) {
        var o = order[k], sl = o[0];
        if (typeof o[1] === "string") {
          if (tur[sl]) continue;
          var c = BASE[o[1]][0];
          if (gold - c < reserve) break;
          gold -= c; tur[sl] = { type: o[1], tier: 1 }; acts.push({ op: "build", slot: sl, type: o[1] });
        } else {
          var t2 = tur[sl];
          if (!t2 || t2.tier >= o[1]) continue;
          var uc = BASE[t2.type][0] * (t2.tier === 1 ? 1 : 2);
          if (gold - uc < reserve) break;
          gold -= uc; t2.tier++; acts.push({ op: "upgrade", slot: sl });
          k--;
        }
      }
      return acts;
    }
    var KB = P.KB, MB = P.MB, AW = P.AW, UR = P.UR, UW = P.UW, SP = P.SP;
    function val(e, eff) {
      var u = Math.min(e.hp, eff);
      if (e.hp <= eff) u += KB * eff;
      if (e.type === "mender") u += MB * eff;
      else if (e.type === "splitter" && e.hp <= eff) u -= SP * eff;
      if (e.remaining < UR) u += UW * eff * (UR - e.remaining) / UR;
      return u;
    }
    function target(t, cands) {
      var type = t.type, d = dmgOf(type, t.tier), n = cands.length, best = cands[0], bs = -1e18, i, j, c, sc;
      if (type === "cannon" || type === "flak") {
        var r2 = type === "cannon" ? 8100 : 4900;
        for (i = 0; i < n; i++) {
          c = cands[i]; sc = 0;
          for (j = 0; j < n; j++) {
            var e = cands[j], dx = e.x - c.x, dy = e.y - c.y;
            if (dx * dx + dy * dy <= r2) sc += val(e, Math.max(1, d - e.armor));
          }
          sc -= c.remaining * 1e-6;
          if (sc > bs) { bs = sc; best = c; }
        }
      } else if (type === "frost") {
        for (i = 0; i < n; i++) {
          c = cands[i];
          sc = (c.slowed ? 0 : 1e6) + (c.type === "splitling" ? 0 : 1e5) + P.FH * c.hp - c.remaining;
          if (sc > bs) { bs = sc; best = c; }
        }
      } else {
        var pierce = type === "lance";
        for (i = 0; i < n; i++) {
          c = cands[i];
          sc = val(c, pierce ? d : Math.max(1, d - c.armor)) + (pierce ? AW * c.armor : 0) - c.remaining * 1e-6;
          if (sc > bs) { bs = sc; best = c; }
        }
      }
      return best.id;
    }
    return { plan: plan, target: target };
  };
}

