load("sim.js"); load(arguments[0]);
var G = JSON.parse(arguments[1]);
function genomeToP(g) {
  var cnt = [], order = [];
  for (var s = 0; s < 16; s++) cnt.push(0);
  for (var i = 0; i < g.seq.length; i++) { var s2 = g.seq[i]; cnt[s2]++; if (cnt[s2] === 1) order.push([s2, g.types[s2]]); else order.push([s2, cnt[s2]]); }
  var P = {}; for (var k in g.par) P[k] = g.par[k]; P.order = order; return P;
}
var PP = genomeToP(G);
var seeds = [7932, 15851, 23770, 31689];
for (var si = 0; si < seeds.length; si++) {
  var shots = [], hits = [], dmg = [], healAmt = 0, curW = 0, leaks = [];
  for (var s = 0; s < 16; s++) { shots.push(0); hits.push(0); }
  var fromW = 0;
  var r0 = rampartSimulate(makeStrat(PP), seeds[si], 12020);
  fromW = Math.floor(r0.score) - 5;
  var rec = {
    onShot: function (t, T, tgt, h) { if ((t - 20) / 40 < fromW) return; shots[T.slot]++; hits[T.slot] += h.length; },
    onLeak: function (t, e, hp) { leaks.push(e.type + "@" + ((t - 20) / 40).toFixed(1)); },
    onHeal: function (t, m) { if ((t - 20) / 40 >= fromW) healAmt++; }
  };
  var r = rampartSimulate(makeStrat(PP), seeds[si], 12020, rec);
  var ticks = r.fallTick - (20 + 40 * fromW);
  var line = "seed " + seeds[si] + " score " + r.score + " lastTicks " + ticks + " heals " + healAmt + "\n";
  for (var s3 = 0; s3 < 16; s3++) line += "  s" + s3 + " " + G.types[s3] + " shots " + shots[s3] + " hits/shot " + (hits[s3] / Math.max(1, shots[s3])).toFixed(2) + "\n";
  print(line + "  leaks " + leaks.join(" "));
}

