var KB = P.KB, MB = P.MB, AW = P.AW, UR = P.UR, UW = P.UW, SP = P.SP, LW = P.LW || 0, RB = P.RB || 0, AR = P.AR || 1;
function val(e, eff) {
  var u = Math.min(e.hp, eff);
  if (e.hp <= eff) u += KB * eff;
  if (e.type === "mender") u += MB * eff;
  else if (e.type === "splitter" && e.hp <= eff) u -= SP * eff;
  var ur = e.air ? UR * AR : UR; if (e.remaining < ur) u += UW * eff * (1 + LW * (e.type === "brute" ? 2 : e.type === "wisp" || e.type === "splitter" || e.type === "mender" ? 1 : 0)) * (ur - e.remaining) / ur;
  if (e.type === "runner") u += RB * eff;
  return u;
}

