load("sim.js"); load("strat4.js");
var G = JSON.parse(arguments[0]);
function genomeToP(g) {
  var cnt = [], order = [];
  for (var s = 0; s < 16; s++) cnt.push(0);
  for (var i = 0; i < g.seq.length; i++) { var s2 = g.seq[i]; cnt[s2]++; if (cnt[s2] === 1) order.push([s2, g.types[s2]]); else order.push([s2, cnt[s2]]); }
  var P = {}; for (var k in g.par) P[k] = g.par[k]; P.order = order; if (g.lateTypes) P.lateTypes = g.lateTypes; return P;
}
var SEEDS = []; for (var i = 1; i <= 48; i++) SEEDS.push(i * 7919 + 13);
function ev(g) { var P = genomeToP(g), s = 0; for (var i = 0; i < SEEDS.length; i++) s += rampartSimulate(makeStrat(P), SEEDS[i], 12020).score; return s / SEEDS.length; }
print("base", ev(G).toFixed(3));
var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
var results = [];
for (var slot = 0; slot < 16; slot++) for (var t = 0; t < 5; t++) {
  if (G.types[slot] === TYPES[t]) continue;
  var g = JSON.parse(JSON.stringify(G)); g.lateTypes = G.types.slice(); g.lateTypes[slot] = TYPES[t];
  g.par.swapWave = 80; g.par.swapHp = 9; g.par.swapKeep = 0;
  results.push([ev(g), slot, TYPES[t]]);
}
results.sort(function (a, b) { return b[0] - a[0]; });
for (var r = 0; r < 12; r++) print(results[r][0].toFixed(3), results[r][1], results[r][2]);

