  var P = {}; for (var k in g.par) P[k] = g.par[k]; P.order = order; return P;
}
var N = parseInt(arguments[1] || "100");
var SEEDS = []; for (var i = 1; i <= N; i++) SEEDS.push((i * 2654435761 + 977) >>> 0);
